import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Test Flow: Inline Scripts with Action Output References
export const flowWithActionOutputInlineScripts = Flow(
    {
        $id: Now.ID['test_flow_action_outputs'],
        name: 'Test - Inline Scripts with Action Outputs',
        description: 'Test flow with inline scripts referencing action outputs',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger_outputs'] },
        {
            table: 'incident',
            condition: 'priority<=2',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Create a task
        wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_create_task'], annotation: 'Create task for incident' },
            {
                table_name: 'task',
                values: `short_description=Follow-up for ${wfa.dataPill(params.trigger.current.number, 'string')}^priority=${wfa.dataPill(params.trigger.current.priority, 'integer')}`,
            }
        )

        // Lookup assignment group
        wfa.action(
            action.core.lookUpRecord,
            { $id: Now.ID['test_lookup_group'], annotation: 'Find assignment group' },
            {
                table: 'sys_user_group',
                conditions: `name=IT Support`,
                // limit: '1',
            }
        )

        // Create approval with inline script
        wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_create_approval'], annotation: 'Create approval with inline script' },
            {
                table_name: 'sysapproval_approver',
                values: wfa.inlineScript(`
                    var reqSysId = fd_data.trigger.current.sys_id;
                    var groupSysId = fd_data._2__look_up_record.record.sys_id || 'admin';
                    return 'source_table=incident^document_id=' + reqSysId + '^approver=' + groupSysId + '^state=requested';
                `),
            }
        )

        // Final summary with action output references
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_log_summary'], annotation: 'Final summary with all context' },
            {
                log_level: 'info',
                log_message: wfa.inlineScript(`
                    var inc = fd_data.trigger.current;
                    var taskId = fd_data.steps.test_create_task.result.record;
                    var approvalId = fd_data.steps.test_create_approval.result.record;
                    var groupId = fd_data._2__look_up_record.record.sys_id || 'N/A';
                    
                    var summary = {
                        incident: inc.number,
                        priority: inc.priority,
                        task: taskId,
                        approval: approvalId,
                        group: groupId,
                        completed: new Date().toISOString()
                    };
                    
                    return 'Flow completed: ' + JSON.stringify(summary);
                `),
            }
        )
    }
)
